import {deliveryStatus} from './workspace-domain.js';
import {money,projectClient,invoiceStatus,saveClient,archiveClient,updateProject,archiveProject,reopenProject,approveMilestone,togglePhase} from './domain.js';

export function createJourneyUI(ctx){
 const {getState:S,open,btn,icon,esc,badge,avatar,date,save,render,toast,dialog}=ctx;
 const project=id=>S().projects.find(p=>p.id===id);
 const commit=message=>{save();render();if(message)toast(message);};
 const field=(label,name,value='',extra='')=>`<label class="field">${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;
 const note=text=>`<div class="notice">${text}</div>`;
 const err='<div class="form-error" role="alert"></div>';
 function projectDetail(id){
  const s=S(),p=project(id),c=projectClient(s,p),bills=s.invoices.filter(i=>i.projectId===id),hours=s.time.filter(t=>t.projectId===id).reduce((a,t)=>a+t.hours,0);
  const canDeliver=!p.archived&&['active','completed'].includes(p.status);
  open('Project',`<div class="dialog-body"><div class="detail-client">${avatar(c)}${esc(c.name)} ${badge(p.archived?'archived':deliveryStatus(p))}</div><h1>${esc(p.name)}</h1><p>${esc(p.service)} · ${p.due?'Target '+date(p.due):'No target date'}</p><div class="action-row">${!p.archived&&p.status!=='cancelled'?btn('Edit project','edit-project',`data-id="${id}"`):''}${p.status==='cancelled'&&!p.archived?btn('Reopen project','reopen-project',`data-id="${id}"`):''}${btn(p.archived?'Restore project':'Archive','archive-project',`data-id="${id}"`)}</div><div class="summary-grid"><div><small>Project fee</small><strong>${p.needsPricing?'Not set':money(p.budget)}</strong></div><div><small>Collected</small><strong>${money(bills.reduce((a,i)=>a+i.paid,0))}</strong></div><div><small>Time tracked</small><strong>${hours.toFixed(1)} h</strong></div></div>
  ${p.inquiry?`<section class="section"><h3>Inquiry</h3><p class="readable">${esc(p.inquiry.scope)}</p>${p.inquiry.answer?`<p class="muted">${esc(p.inquiry.question)}<br>${esc(p.inquiry.answer)}</p>`:''}<span class="badge">${esc(p.inquiry.tag)}</span></section>`:''}
  ${ctx.projectDocuments(id)}
  <section class="section"><h3>Delivery phases</h3>${p.phases.map((f,i)=>{const rules=p.billingPlan.filter(r=>r.phaseId===f.id),amount=rules.reduce((a,r)=>a+r.amount,0);return `<div class="phase-row"><span class="phase-check ${f.done?'done':''}">${f.done?icon('check'):i+1}</span><span class="phase-label">${esc(f.name)}${rules.length?`<small>${money(amount)} on approval</small>`:''}</span>${rules.length?(f.approved?'<span class="badge active">Approved</span>':btn('Approve','approve-preview',`data-id="${id}" data-phase="${f.id}" ${canDeliver?'':'disabled'}`)):btn(f.done?'Reopen':'Complete','complete-phase',`data-id="${id}" data-phase="${f.id}" ${canDeliver?'':'disabled'}`)}</div>`;}).join('')}${!canDeliver?'<p class="hint">Delivery actions are available after the deposit is paid.</p>':''}</section>
  <section class="section"><h3>Billing schedule</h3>${p.accepted?schedule(p,bills):'<p class="muted">No agreed billing schedule yet. Configure it in a linked document.</p>'}${p.accepted&&p.billingPlan.some(r=>!r.phaseId)&&!bills.some(i=>i.kind==='deposit')&&!p.archived&&p.status!=='cancelled'?btn('Create deposit invoice','deposit',`data-id="${id}"`):''}<div class="list-line"><span class="muted">Total invoiced</span><strong>${money(bills.reduce((a,i)=>a+i.amount,0))}</strong></div></section><div class="action-row">${btn(icon('clock')+'Log time','log-time',`data-id="${id}"`)}${btn('Client portal preview','portal',`data-id="${id}"`)}</div></div>`,{drawer:true});
 }
 function schedule(p,bills=[]){return p.billingPlan.length?p.billingPlan.map(r=>{const i=bills.find(i=>i.ruleId===r.id);return `<div class="billing-line"><span><strong>${esc(r.name)}</strong><small>${r.phaseId?'On approval: '+esc(p.phases.find(f=>f.id===r.phaseId)?.name||'Milestone'):'On document completion'}</small></span><span class="billing-amount">${money(r.amount)}${i?`<button class="text-btn" data-action="invoice" data-id="${i.id}">${i.number} · ${invoiceStatus(i)}</button>`:'<small>Scheduled</small>'}</span></div>`;}).join(''):'<p class="muted">Set the project fee and billing schedule in Documents.</p>';}
 function clientDetail(id){if(ctx.clientDetail)return ctx.clientDetail(id);const s=S(),c=s.clients.find(c=>c.id===id);open('Client',`<div class="dialog-body"><div class="detail-client">${avatar(c)}${esc(c.tag)} ${c.archived?badge('archived'):''}</div><h1>${esc(c.name)}</h1><p>${esc(c.contact)} · ${esc(c.email)}</p><div class="action-row">${btn('Edit client','edit-client',`data-id="${id}"`)}${btn(c.archived?'Restore client':'Archive','archive-client',`data-id="${id}"`)}</div><section class="section"><h3>Projects</h3>${s.projects.filter(p=>p.clientId===id).map(p=>`<button class="list-line full-width" data-action="project" data-id="${p.id}"><span>${esc(p.name)}</span>${badge(p.archived?'archived':deliveryStatus(p))}</button>`).join('')||'<p class="muted">No projects yet.</p>'}</section>${!c.archived?`<div class="action-row">${btn(icon('plus')+'New project','new-project',`data-client="${id}"`,'primary')}</div>`:''}</div>`,{drawer:true});}
 function clientForm(id){const c=S().clients.find(c=>c.id===id)||{};open(id?'Edit client':'New client',`<form id="client-form" data-id="${id||''}"><div class="dialog-body">${field('Client or business name','name',c.name,'required maxlength="100"')}${field('Contact name','contact',c.contact,'required maxlength="100"')}${field('Email address','email',c.email,'type="email" required')}${field('Service or tag','tag',c.tag,'maxlength="60"')}<p class="hint">Issued invoices and published proposals keep their original client details.</p>${err}</div><div class="dialog-footer">${btn('Cancel','close')}<button class="btn primary" type="submit">${id?'Save client':'Add client'}</button></div></form>`);}
 function editProject(id){const p=project(id);open('Edit project',`<form id="project-edit-form" data-id="${id}"><div class="dialog-body">${field('Project name','name',p.name,'required maxlength="100"')}${field('Service','service',p.service,'maxlength="80"')}${field('Target date','due',p.due,'type="date"')}<label class="field">Status<select name="status">${[...new Set([p.status,...(p.accepted?['active','completed','cancelled']:['cancelled'])])].map(st=>`<option value="${st}" ${p.status===st?'selected':''}>${['inquiry','proposal','declined'].includes(st)?'Planned':st[0].toUpperCase()+st.slice(1)}</option>`).join('')}</select></label>${note(p.accepted?'Agreed scope, fees, and payment terms are preserved in Documents.':'Edit scope, fees, and payment terms in the linked billing document.')}${err}</div><div class="dialog-footer">${btn('Cancel','project',`data-id="${id}"`)}<button class="btn primary" type="submit">Save project</button></div></form>`);}
 function approvePreview(id,phaseId){const p=project(id),f=p.phases.find(f=>f.id===phaseId),rules=p.billingPlan.filter(r=>r.phaseId===phaseId);const pending=rules.filter(r=>!S().invoices.some(i=>i.ruleId===r.id&&i.projectId===id));open('Approve milestone',`<div class="dialog-body"><h1>${esc(f.name)}</h1><p>Mark this phase approved and ${pending.length?`create ${pending.length===1?'an invoice':'invoices'} for ${money(pending.reduce((a,r)=>a+r.amount,0))}`:'keep its existing invoices'}. No email or payment request will be sent.</p>${err}</div>`,{footer:btn('Cancel','project',`data-id="${id}"`)+btn('Approve milestone','approve-milestone',`data-id="${id}" data-phase="${phaseId}"`,'accent')});}
 function portal(id='p1'){const p=project(id)||S().projects[0],c=projectClient(S(),p);open('Client portal preview',`<div class="dialog-body"><div class="preview-role">CLIENT VIEW · ${esc(S().settings.business)}</div><h1>${esc(p.name)}</h1><p>${esc(c.name)}</p><h3>Project status</h3>${badge(deliveryStatus(p))}<section class="section"><h3>Delivery phases</h3>${p.phases.map((f,i)=>`<div class="phase-row"><span class="phase-check ${f.done?'done':''}">${f.done?icon('check'):i+1}</span>${esc(f.name)}<small>${f.approved?'Approved':f.done?'Complete':'Upcoming'}</small></div>`).join('')}</section>${ctx.projectDocuments(p.id,true)}<section class="section"><h3>Invoices</h3>${S().invoices.filter(i=>i.projectId===p.id).map(i=>`<div class="list-line"><span>${i.number} · ${money(i.amount)}</span>${badge(invoiceStatus(i))}</div>`).join('')||'<p class="muted">No invoices.</p>'}</section><p class="hint">Local preview only. Secure client access will be added with the server implementation.</p></div>`,{drawer:true});}
 function handleClick(a,el){const id=el.dataset.id;
  if(a==='edit-client')clientForm(id);
  else if(a==='archive-client'){const c=S().clients.find(c=>c.id===id);if(c.archived){archiveClient(S(),id);commit('Client restored.');clientDetail(id);}else open('Archive client?',`<div class="dialog-body"><p>Hide ${esc(c.name)} from the active client list. Existing projects, documents, and invoices remain available. You can restore this client later.</p></div>`,{footer:btn('Cancel','client',`data-id="${id}"`)+btn('Archive client','archive-client-confirm',`data-id="${id}"`)});}
  else if(a==='archive-client-confirm'){archiveClient(S(),id);commit('Client archived.');clientDetail(id);}
  else if(a==='edit-project')editProject(id);
  else if(a==='archive-project'){const p=project(id);if(p.archived){archiveProject(S(),id);commit('Project restored.');projectDetail(id);}else open('Archive project?',`<div class="dialog-body"><p>Hide ${esc(p.name)} from active project lists and pause its delivery actions. Existing invoices remain payable. You can restore it later.</p></div>`,{footer:btn('Cancel','project',`data-id="${id}"`)+btn('Archive project','archive-project-confirm',`data-id="${id}"`)});}
  else if(a==='archive-project-confirm'){archiveProject(S(),id);commit('Project archived.');projectDetail(id);}
  else if(a==='reopen-project'){reopenProject(S(),id);commit('Project reopened.');projectDetail(id);}
  else if(a==='approve-preview')approvePreview(id,el.dataset.phase);
  else if(a==='approve-milestone'){const bills=approveMilestone(S(),id,el.dataset.phase);commit(bills.length?'Milestone approved. Invoice is available in the billing schedule.':'Phase approved.');projectDetail(id);}
  else if(a==='complete-phase'){togglePhase(S(),id,el.dataset.phase);commit('Phase updated.');projectDetail(id);}
  else return false;return true;
 }
 function handleSubmit(form,v,intent){const id=form.dataset.id;
  if(form.id==='client-form'){const c=saveClient(S(),v,id||undefined);commit(id?'Client updated.':'Client created.');clientDetail(c.id);}
  else if(form.id==='project-edit-form'){updateProject(S(),id,v);commit('Project updated.');projectDetail(id);}
  else return false;return true;
 }
 function handleInput(){}
 return{projectDetail,clientDetail,clientForm,portal,handleClick,handleSubmit,handleInput};
}
